(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 18 + Math.cos(y * 0.013 - t * 0.18) * 12;
  const w1y = Math.cos(y * 0.019 - t * 0.22) * 18 + Math.sin(x * 0.016 + t * 0.3) * 12;
  const w2x = Math.sin((x + w1x) * 0.012 + t * 0.15) * 8;
  const w2y = Math.cos((y + w1y) * 0.014 - t * 0.12) * 8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 2.1, 0.6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*40, 0.07, 1.8, 1.3],
    [200+Math.sin(t*0.25+4)*110, 220+Math.cos(t*0.45+3)*70, 0.08, 2.4, 0.85]
  ];
  let aS = 0, iS = 0, aS2 = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    const wave2 = Math.sin(d*f*1.618 - t*sp*0.618);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    aS2 += wave2 * w * 0.4;
  }
  const n = 9;
  const act = aS/n, inh = iS/n, harm = aS2/n;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.0))/2 + Math.sin((sx+sy)*0.11+t*2.2)*0.15 + Math.sin((sx-sy)*0.09-t*1.8)*0.15;
  const bg2 = Math.sin(sx*0.06+sy*0.04+t*1.5)*0.3 + Math.cos(sx*0.05-sy*0.07-t*1.2)*0.3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.3) + Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const spiral2 = Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const lap = (Math.sin(sx*0.12+t*0.8)*Math.sin(sy*0.12-t*0.6) + Math.sin((sx-sy)*0.08+t)*Math.cos((sx+sy)*0.08-t*0.5))*0.25;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + bg2*0.1 + spiral + spiral2 + harm*0.3 + lap)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t)*0.4 + Math.cos(sx*0.07-sy*0.11+t*0.7)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.25+sy*0.2+t*3)*Math.cos(sx*0.2-sy*0.25-t*2.5)*0.1;
  const blend = reaction*0.6 + cell*0.2 + micro*0.05 + Math.tanh(harm*1.5)*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[12,45,85],[18,85,120],[25,135,130],[80,170,140],
    [170,190,90],[210,175,60],[215,130,65],[185,75,70],[130,40,80],
    [75,20,65],[35,12,55],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const r0 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65 ? 1.0 + (Math.abs(reaction)-0.65)*0.6 : 1.0;
  const glow = Math.max(0, Math.sin(reaction*Math.PI*2)*0.15);
  return [
    Math.min(255, ((r0 + glow*60)*lum*edge)|0),
    Math.min(255, ((g0 + glow*80)*lum*edge)|0),
    Math.min(255, ((b0 + glow*40)*lum*edge)|0)
  ];
}
